import polars as pl
from pathlib import Path

# Reconstruct what the universal pool SHOULD include
project_root = Path("/home/wessel/code/kraken")

# 1. Load GESP data and filter to Final GESP >= 10
gesp_file = project_root / "data/Hu_et_al_2021_GESPs.csv"
gesp_genes = set()
if gesp_file.exists():
    gesp_df = pl.read_csv(gesp_file, separator=';')
    for row in gesp_df.iter_rows(named=True):
        gene = row.get("HGNC Symbol", "").strip()
        final_score_str = str(row.get("Final GESP Score ", "0")).replace(",", ".")
        try:
            final_score = float(final_score_str)
            if final_score >= 10 and gene:
                gesp_genes.add(gene)
        except ValueError:
            pass
    print(f"GESP >= 10: {len(gesp_genes)} genes")

    # Check if CDH17 is in this set
    if "CDH17" in gesp_genes:
        print("  CDH17 is in GESP >= 10 set ✓")
    else:
        print("  CDH17 is NOT in GESP >= 10 set ✗")

# 2. Load competitor targets
competition_file = project_root / "data/competition.csv"
competitor_genes = set()
if competition_file.exists():
    comp_df = pl.read_csv(competition_file)
    for row in comp_df.iter_rows(named=True):
        targets = row.get("targets_parsed", "")
        if targets:
            for t in targets.replace(";", ",").split(","):
                t = t.strip()
                if t:
                    competitor_genes.add(t)
    print(f"Competitor targets: {len(competitor_genes)} unique targets")

    # Check if CDH17 is in this set
    if "CDH17" in competitor_genes:
        print("  CDH17 is in competitor targets ✓")
    else:
        print("  CDH17 is NOT in competitor targets ✗")

# 3. Union
all_gene_names = list(gesp_genes | competitor_genes)
print(f"\nUniversal pool should have: {len(all_gene_names)} unique genes")
print(f"  - GESP >= 10: {len(gesp_genes)} genes")
print(f"  - Competitor-only: {len(competitor_genes - gesp_genes)} genes")

if "CDH17" in all_gene_names:
    print("\nCDH17 should be in universal pool ✓")
else:
    print("\nCDH17 should NOT be in universal pool ✗")

EOF
